package cn.mop.persistence;

import cn.mop.domain.*;
import cn.mop.domain.calendar.*;
import cn.mop.domain.calendar.WorkingCalendarRepository.*;
import cn.mop.domain.time.IntervalSets.Interval;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import com.zaxxer.hikari.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import java.sql.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Supplier;
import static org.junit.jupiter.api.Assertions.*;

/** Runtime-role real PostgreSQL; all committed examples are synthetic unpublished drafts. */
@EnabledIfEnvironmentVariable(named="MOP_RUN_REMOTE_TESTS",matches="true")
class PostgresWorkingCalendarIntegrationTest {
    static final String TENANT="55000000-0000-4000-8000-000000000001",OTHER="55000000-0000-4000-8000-000000000002";
    static HikariDataSource pool;static ObjectMapper mapper;static PostgresPlatformRepository platform;static PostgresWorkingCalendarRepository calendars;static String admin;
    static final Instant START=Instant.parse("2026-10-01T00:00:00Z"),END=START.plus(Duration.ofDays(7));
    @BeforeAll static void connect(){assertTrue(System.getenv("SPRING_DATASOURCE_URL").matches("jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/mop_test"));assertEquals("mop_test_runtime",System.getenv("SPRING_DATASOURCE_USERNAME"));pool=pool(6);mapper=new ObjectMapper().registerModule(new JavaTimeModule()).disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);platform=new PostgresPlatformRepository(pool,mapper);calendars=new PostgresWorkingCalendarRepository(pool,platform);admin=actor("padmin");assertEquals(List.of(),calendars.readinessProblems());}
    @AfterAll static void close(){if(pool!=null)pool.close();}
    static HikariDataSource pool(int size){var cfg=new HikariConfig();cfg.setJdbcUrl(System.getenv("SPRING_DATASOURCE_URL"));cfg.setUsername(System.getenv("SPRING_DATASOURCE_USERNAME"));cfg.setPassword(System.getenv("SPRING_DATASOURCE_PASSWORD"));cfg.setMaximumPoolSize(size);cfg.setConnectionTimeout(5000);return new HikariDataSource(cfg);}
    static String actor(String role){return platform.users().stream().filter(u->platform.membership(u.id(),TENANT).filter(m->m.role().equals(role)).isPresent()).findFirst().orElseThrow().id();}
    static Access access(String actor){return new Access(actor,TENANT,platform.membership(actor,TENANT).orElseThrow().permissionVersion(),UUID.randomUUID().toString());}
    static Access access(){return access(admin);}
    static WorkingCalendarDraft draft(String name){return new WorkingCalendarDraft(name,new Interval(START,END),List.of(new Interval(START.plusSeconds(3600),START.plusSeconds(7200)),new Interval(START,START.plusSeconds(4000))),true,"  合成草稿说明😀\n原文\t ");}
    static Object command(Access a,String id,String route,String key,String hash,Supplier<Object> action){return platform.idempotentAuthorized(a.actorId(),a.tenantId(),route,key,hash,a.permissionVersion(),()->calendars.authorizeCurrentAccess(a,id),action);}
    static Snapshot create(){Access a=access();return (Snapshot)command(a,null,"POST /integration/calendar",UUID.randomUUID().toString(),"a".repeat(64),()->calendars.create(a,draft("合成日历 "+UUID.randomUUID())));}
    static Snapshot update(Snapshot old,WorkingCalendarDraft value){Access a=access();return (Snapshot)command(a,old.id(),"PATCH /integration/calendar/"+old.id(),UUID.randomUUID().toString(),"b".repeat(64),()->calendars.update(a,old.id(),old.version(),value));}
    static JsonNode json(Object value){try{return mapper.readTree(mapper.writeValueAsBytes(value));}catch(Exception e){throw new AssertionError(e);}}
    static long count(String sql,String id)throws SQLException{try(var c=pool.getConnection();var s=c.prepareStatement(sql)){if(id!=null)s.setString(1,id);try(var r=s.executeQuery()){r.next();return r.getLong(1);}}}
    static long audits(String id)throws SQLException{return count("SELECT count(*) FROM mop_audit WHERE payload->>'resource_id'=? AND payload->>'action' LIKE 'working_calendar.draft.%'",id);}
    @Test void rawWindowsAndNotesRoundTripAndStayUnpublished()throws Exception{Snapshot saved=create();var independent=new PostgresWorkingCalendarRepository(pool,new PostgresPlatformRepository(pool,mapper));assertEquals(saved,independent.get(access(),saved.id()));assertFalse(saved.draft().effective());assertEquals("UNVERIFIED",saved.draft().customerConfirmation());assertEquals(2,saved.draft().workingWindows().size());assertEquals(1,saved.draft().normalizedWindows().size());assertEquals(1,audits(saved.id()));assertEquals(2,count("SELECT count(*) FROM mop_configuration WHERE key IN ('sla.tenant_work_calendar','sla.basic_standard_p3_next_day') AND registry_json->'value'='null'::jsonb",null));}
    @Test void immutableHistoryPreservesBeforeAfterAndCreatedTime(){Snapshot first=create(),second=update(first,draft("第二版本")),third=update(second,draft("第三版本"));assertEquals(3,third.version());assertEquals(first.createdAt(),third.createdAt());assertFalse(third.updatedAt().isBefore(second.updatedAt()));var history=calendars.history(access(),first.id(),2,null);assertEquals(List.of(3L,2L),history.stream().map(Revision::version).toList());assertEquals(second.draft(),history.get(0).before());assertEquals(third.draft(),history.get(0).after());assertEquals(first.draft(),history.get(1).before());var tail=calendars.history(access(),first.id(),2,2L);assertEquals(1,tail.size());assertNull(tail.get(0).before());assertEquals(first.draft(),tail.get(0).after());}
    @Test void onlyCurrentConfigurationAdministratorsHaveAccess(){Snapshot saved=create();for(String role:List.of("msp","viewer","tadmin")){Access a=access(actor(role));assertEquals(403,assertThrows(DomainException.class,()->calendars.get(a,saved.id())).status);assertEquals(403,assertThrows(DomainException.class,()->command(a,saved.id(),"PATCH /integration/calendar/"+saved.id(),UUID.randomUUID().toString(),"a".repeat(64),()->calendars.update(a,saved.id(),1,draft("forbidden")))).status);}Access old=access();Access stale=new Access(old.actorId(),old.tenantId(),old.permissionVersion()+1,old.traceId());assertEquals(401,assertThrows(DomainException.class,()->calendars.list(stale,10,null,null)).status);}
    @Test void foreignTenantAndMissingObjectsAre404(){Snapshot saved=create();var membership=platform.membership(admin,OTHER).orElseThrow();Access other=new Access(admin,OTHER,membership.permissionVersion(),UUID.randomUUID().toString());assertEquals(404,assertThrows(DomainException.class,()->calendars.get(other,saved.id())).status);assertEquals(404,assertThrows(DomainException.class,()->calendars.history(other,saved.id(),10,null)).status);assertEquals(404,assertThrows(DomainException.class,()->command(other,saved.id(),"PATCH /integration/calendar/"+saved.id(),UUID.randomUUID().toString(),"a".repeat(64),()->calendars.update(other,saved.id(),1,draft("foreign")))).status);assertEquals(404,assertThrows(DomainException.class,()->calendars.get(access(),UUID.randomUUID().toString())).status);}
    @Test void writesOutsideProtectedTransactionAreRejected(){Snapshot saved=create();assertThrows(IllegalStateException.class,()->calendars.create(access(),draft("no transaction")));assertThrows(IllegalStateException.class,()->calendars.update(access(),saved.id(),1,draft("no transaction")));assertThrows(IllegalStateException.class,()->calendars.authorizeCurrentAccess(access(),null));}
    @Test void originalReceiptReplaysWithoutExtraRevisionAndMismatchConflicts()throws Exception{Snapshot first=create();Access a=access();String key=UUID.randomUUID().toString(),route="PATCH /integration/calendar/"+first.id();Snapshot saved=(Snapshot)command(a,first.id(),route,key,"c".repeat(64),()->calendars.update(a,first.id(),1,draft("changed")));Object replay=command(a,first.id(),route,key,"c".repeat(64),()->{throw new AssertionError("cached");});assertEquals(json(saved),json(replay));assertEquals(409,assertThrows(DomainException.class,()->command(a,first.id(),route,key,"d".repeat(64),()->null)).status);assertEquals(2,calendars.history(a,first.id(),10,null).size());assertEquals(2,audits(first.id()));}
    @Test void replayGuardRunsBeforeReceiptAndMissingScopeCannotBypass(){Snapshot first=create();Access a=access();String key=UUID.randomUUID().toString(),route="PATCH /integration/calendar/"+first.id();Object saved=command(a,first.id(),route,key,"c".repeat(64),()->calendars.update(a,first.id(),1,draft("guarded")));assertEquals(404,assertThrows(DomainException.class,()->command(a,UUID.randomUUID().toString(),route,key,"c".repeat(64),()->null)).status);assertEquals(json(saved),json(command(a,first.id(),route,key,"c".repeat(64),()->null)));}
    @Test void staleCASDoesNotAppendHistoryOrAudit()throws Exception{Snapshot first=create(),second=update(first,draft("winner"));assertEquals(409,assertThrows(DomainException.class,()->update(first,draft("stale"))).status);assertEquals(second,calendars.get(access(),first.id()));assertEquals(2,calendars.history(access(),first.id(),10,null).size());assertEquals(2,audits(first.id()));}
    @Test void thrownCommandRollsBackHeadRevisionAuditAndReceipt()throws Exception{Snapshot first=create();Access a=access();String key=UUID.randomUUID().toString(),route="PATCH /integration/calendar/"+first.id();assertThrows(IllegalStateException.class,()->command(a,first.id(),route,key,"c".repeat(64),()->{calendars.update(a,first.id(),1,draft("rolled back"));throw new IllegalStateException("synthetic rollback");}));assertEquals(first,calendars.get(a,first.id()));assertEquals(1,audits(first.id()));Snapshot retried=(Snapshot)command(a,first.id(),route,key,"c".repeat(64),()->calendars.update(a,first.id(),1,draft("retry")));assertEquals(2,retried.version());}
    @Test void competingCASHasExactlyOneWinner()throws Exception{Snapshot first=create();var start=new CountDownLatch(1);var exec=Executors.newFixedThreadPool(2);try{List<Future<Integer>> futures=new ArrayList<>();for(int i=0;i<2;i++){final int n=i;futures.add(exec.submit(()->{start.await();try{update(first,draft("candidate "+n));return 200;}catch(DomainException e){return e.status;}}));}start.countDown();List<Integer> statuses=new ArrayList<>();for(var f:futures)statuses.add(f.get(15,TimeUnit.SECONDS));Collections.sort(statuses);assertEquals(List.of(200,409),statuses);assertEquals(2,calendars.history(access(),first.id(),10,null).size());assertEquals(2,audits(first.id()));}finally{exec.shutdownNow();}}
    @Test void boundedListAndHistoryCursorAndReadOnlyAudit()throws Exception{create();create();long before=count("SELECT count(*) FROM mop_audit",null);var page=calendars.list(access(),2,null,null);assertEquals(2,page.size());Snapshot last=page.get(1);var next=calendars.list(access(),2,last.createdAt(),last.id());assertTrue(next.stream().noneMatch(x->page.stream().anyMatch(y->x.id().equals(y.id()))));calendars.get(access(),last.id());calendars.history(access(),last.id(),1,null);assertEquals(before,count("SELECT count(*) FROM mop_audit",null));assertEquals(400,assertThrows(DomainException.class,()->calendars.list(access(),102,null,null)).status);assertEquals(400,assertThrows(DomainException.class,()->calendars.history(access(),last.id(),10,0L)).status);}
    @Test void emptyIncompleteAndUnicodeMaximumPersistWithoutDefaults(){Snapshot first=create();var explicit=new WorkingCalendarDraft("😀".repeat(100),new Interval(START,END),List.of(),false,"😀".repeat(2000));Snapshot saved=update(first,explicit);assertEquals(explicit,saved.draft());assertNull(saved.draft().preview(saved.id(),saved.version(),START,Duration.ofHours(1)).scenarioDeadline());assertNull(saved.draft().preview(saved.id(),saved.version(),START,Duration.ZERO).effectiveDeadline());}
    @Test void singleConnectionReadsAndClosedPoolFailWithoutFallback(){Snapshot first=create();var single=pool(1);var reader=new PostgresWorkingCalendarRepository(single,new PostgresPlatformRepository(single,mapper));assertEquals(first,reader.get(access(),first.id()));assertEquals(1,reader.history(access(),first.id(),1,null).size());assertEquals(List.of(),reader.readinessProblems());single.close();assertEquals(List.of("WORKING_CALENDAR_SCHEMA_OR_ACCESS_UNAVAILABLE"),reader.readinessProblems());assertEquals(503,assertThrows(DomainException.class,()->reader.get(access(),first.id())).status);}
    @Test void sameKeyConcurrentRequestsShareOneCommittedRevisionAndReceipt()throws Exception{
        Snapshot first=create();Access a=access();String key=UUID.randomUUID().toString(),route="PATCH /integration/calendar/"+first.id();var latch=new CountDownLatch(1);var exec=Executors.newFixedThreadPool(2);
        try{List<Future<Object>> futures=new ArrayList<>();for(int i=0;i<2;i++)futures.add(exec.submit(()->{latch.await();return command(a,first.id(),route,key,"e".repeat(64),()->calendars.update(a,first.id(),1,draft("same request")));}));latch.countDown();assertEquals(json(futures.get(0).get(15,TimeUnit.SECONDS)),json(futures.get(1).get(15,TimeUnit.SECONDS)));assertEquals(2,calendars.history(a,first.id(),10,null).size());assertEquals(2,audits(first.id()));}finally{exec.shutdownNow();}
    }

}
